public class DivByK {

    public static long countDivisible(int[] a, int k) {
        long[] byRemainder = new long[k];
        byRemainder[0] = 1; // the empty prefix has remainder 0
        long prefix = 0, count = 0;
        for (int x : a) {
            prefix += x;
            int r = (int) (((prefix % k) + k) % k); // Java's % can be negative
            count += byRemainder[r];
            byRemainder[r]++;
        }
        return count;
    }
}

